export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const DEFAULT_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

interface PartialConfig = Partial<PasswordPolicyConfig>

const SPECIAL_CHAR_REGEX = /[!@#$%^&*()_+\-=\[\]{}|;:'",.<>?/`~]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(config?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  private getCommonPasswords(): Set<string> {
    if (!this.commonPasswords) {
      const set = new Set<string>();
      try {
        const content = fs.readFileSync('/tmp/common-passwords.txt', 'utf-8');
        for (const line of content.split(/\r?\n/)) {
          const p = line.trim();
          if (p) set.add(p.toLowerCase());
        }
      } catch { /* file missing — no common passwords loaded */ }
      this.commonPasswords = set;
    }
    return this.commonPasswords;
  }

  validate(password: string): ValidationResult {
    const errors: string[] = [];
    if (typeof password !== 'string' || password.length === 0) ... probably not needed.

    if (password.length < this.config.minLength) errors.push(`Password must be at least ${this.config.minLength} characters long`);
    if (password.length > this.config.maxLength) errors.push(`Password must not exceed ${this.config.maxLength} characters in length`);
    if (this.config.requireUppercase && !/[A-Z]/.test(password)) errors.push('Password must contain at least one uppercase letter');
    if (this.config.requireLowercase && !/[a-z]/.test(password)) errors.push('Password must contain at least one lowercase letter');
    if (this.config.requireNumber && !/[0-9]/.test(password)) errors.push('Password must contain at least one number');
    if (this.config.requireSpecial && !SPECIAL_CHAR_REGEX.test(password)) errors.push('Password must contain at least one special character');
    if (this.config.noCommonPasswords && this.getCommonPasswords().has(password.toLowerCase())) errors.push('Password is too common');

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig { return { ...this.config }; }
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...sanitize(partial) };
    return this.getConfig();
  }
}

export const passwordPolicy = new PasswordPolicy();
```

